class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        n = len(nums)
        cnt = defaultdict(int)          # count of sub‑arrays containing a value

        # enumerate all sub‑arrays of length k
        for start in range(n - k + 1):
            window = nums[start:start + k]
            for v in window:
                cnt[v] += 1

        # collect numbers that appear in exactly one sub‑array
        candidates = [value for value, times in cnt.items() if times == 1]

        if not candidates:
            return -1
        return max(candidates)

class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        # iterate over all possible start positions
        for i in range(n - k + 1):
            c = s[i]
            # 1) check that the substring of length k consists of the same character
            all_same = True
            for j in range(i, i + k):
                if s[j] != c:
                    all_same = False
                    break
            if not all_same:
                continue

            # 2) character before the substring must be different (if it exists)
            if i > 0 and s[i-1] == c:
                continue

            # 3) character after the substring must be different (if it exists)
            if i + k < n and s[i+k] == c:
                continue

            # all conditions satisfied
            return True

        return False

