class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        pref = [0] * (n + 1)
        for i in range(n):
            pref[i + 1] = pref[i] + nums[i]

        INF_NEG = -10**18
        # dp[t][i] = max sum with t subarrays using first i elements (prefix of length i)
        dp = [[INF_NEG] * (n + 1) for _ in range(k + 1)]
        for i in range(n + 1):
            dp[0][i] = 0                     # choose 0 subarrays -> sum 0

        for t in range(1, k + 1):
            for i in range(1, n + 1):
                # option 1: skip element i-1
                best = dp[t][i - 1]

                # option 2: take a subarray that ends at i-1, length at least m
                # start index j can be from 0 to i-m
                if i >= m:
                    # enumerate all possible starts
                    for j in range(i - m, -1, -1):
                        # subarray nums[j .. i-1] length = i-j >= m
                        current = dp[t - 1][j] + pref[i] - pref[j]
                        if current > best:
                            best = current
                dp[t][i] = best

        return dp[k][n]

