class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        """
        Returns the sum of all elements that are strictly greater than the elements
        at positions i-k and i+k (if those positions exist).
        """
        n = len(nums)
        total = 0
        for i in range(n):
            good = True
            left = i - k
            if 0 <= left < n and nums[i] <= nums[left]:
                good = False
            right = i + k
            if 0 <= right < n and nums[i] <= nums[right]:
                good = False
            if good:
                total += nums[i]
        return total

