class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        # collect elements of each diagonal identified by i - j
        diag_vals = defaultdict(list)
        for i in range(n):
            for j in range(n):
                d = i - j
                diag_vals[d].append(grid[i][j])

        # decide order for each diagonal and sort accordingly
        diag_sorted = {}
        for d, vals in diag_vals.items():
            # first cell of this diagonal
            r = max(0, d)
            c = max(0, -d)
            if r >= c:                     # bottom‑left triangle (including main diagonal)
                diag_sorted[d] = sorted(vals, reverse=True)   # descending
            else:                          # top‑right triangle
                diag_sorted[d] = sorted(vals)                # ascending

        # write back the sorted values
        for i in range(n):
            for j in range(n):
                d = i - j
                # pop from the front of the sorted list for the current diagonal
                # use an index pointer stored per diagonal for O(1) access
                # (conversion to iterator list already sorted)
                # We'll keep a cursor per diagonal.
                # Initialize cursors lazily.
                if not hasattr(self, "_cursor"):
                    self._cursor = {}
                if d not in self._cursor:
                    self._cursor[d] = 0
                idx = self._cursor[d]
                grid[i][j] = diag_sorted[d][idx]
                self._cursor[d] = idx + 1

        # clean up the temporary attribute
        if hasattr(self, "_cursor"):
            del self._cursor
        return grid

class Solution:
    def maxDifference(self, s: str) -> int:
        # count frequencies of each lowercase letter
        freq = [0] * 26
        for ch in s:
            freq[ord(ch) - ord('a')] += 1

        odd_max = -1          # will hold the maximum odd frequency
        even_min = float('inf')  # will hold the minimum even frequency

        for cnt in freq:
            if cnt == 0:
                continue
            if cnt % 2 == 1:               # odd frequency
                if cnt > odd_max:
                    odd_max = cnt
            else:                           # even frequency
                if cnt < even_min:
                    even_min = cnt

        # according to the problem constraints both groups are non‑empty
        return odd_max - even_min

