            limit = int(math.isqrt(g))
            for d in range(1, limit + 1):
                if g % d != 0:
                    continue
                # divisor d
                idx_d = first_index[d] if d <= max_val else None
                if idx_d is not None:
                    if best is None or idx_d < best:
                        best = idx_d
                # complementary divisor g//d
                comp = g // d
                if comp != d:
                    idx_c = first_index[comp] if comp <= max_val else None
                    if idx_c is not None:
                        if best is None or idx_c < best:
                            best = idx_c
            ans.append(best if best is not None else -1)
        return ans

