class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        # binary search on answer X
        low = 0
        high = max(points) * m   # maximal possible min score

        while low < high:
            mid = (low + high + 1) // 2   # candidate minimum score
            # compute required moves = sum ceil(mid / points[i])
            moves = 0
            for p in points:
                # early break when moves already exceeds m to speed up
                moves += (mid + p - 1) // p
                if moves > m:
                    break
            if moves <= m:
                low = mid
            else:
                high = mid - 1
        return low

