from functools import lru_cache

class Solution:
    def minCost(self, nums: List[int]) -> int:
        # recursive DP with memoisation over a tuple representing the current list
        @lru_cache(maxsize=None)
        def solve(state: tuple) -> int:
            m = len(state)
            if m <= 2:
                return max(state) if state else 0   # empty list costs 0
            # consider three possible pairs among the first three indices
            best = float('inf')
            # pair (0,1)
            cost = max(state[0], state[1]) + solve(state[2:])
            if cost < best:
                best = cost
            # pair (0,2)
            cost = max(state[0], state[2]) + solve((state[1],) + state[3:])
            if cost < best:
                best = cost
            # pair (1,2)
            cost = max(state[1], state[2]) + solve((state[0],) + state[3:])
            if cost < best:
                best = cost
            return best

        return solve(tuple(nums))

