class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # dp[parity][sum] -> set of reachable products (product <= limit)
        dp: List[Dict[int, Set[int]]] = [{}, {}]   # parity = 0 (even length), 1 (odd length)

        for x in nums:
            ndp: List[Dict[int, Set[int]]] = [{}, {}]

            # 1) skip current element -> copy existing states
            for parity in (0, 1):
                for s, prods in dp[parity].items():
                    ndp[parity].setdefault(s, set()).update(prods)

            # 2) start a new subsequence consisting only of x
            if x <= limit:
                ndp[1].setdefault(x, set()).add(x)   # sum = +x, next parity = 1

            # 3) extend existing subsequences
            for parity in (0, 1):
                for s, prods in dp[parity].items():
                    for prod in prods:
                        new_prod = prod * x
                        if new_prod > limit:
                            continue
                        if parity == 0:               # x will be placed at even index
                            new_sum = s + x
                        else:                         # odd index
                            new_sum = s - x
                        new_parity = 1 - parity
                        ndp[new_parity].setdefault(new_sum, set()).add(new_prod)

            dp = ndp

        # collect all reachable products with alternating sum k
        best = -1
        for parity in (0, 1):
            if k in dp[parity]:
                best = max(best, max(dp[parity][k]))

        return best

