class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        # Convert points to tuples for faster indexing
        pts = [tuple(p) for p in points]
        n = len(pts)

        # maximum possible Manhattan distance in the square
        max_dist = 2 * side

        # helper: check if we can select k points with min Manhattan distance >= d
        def feasible(d: int) -> bool:
            chosen = []

            def dfs(start: int) -> bool:
                if len(chosen) == k:
                    return True
                # pruning: not enough points left to reach k
                if n - start + len(chosen) < k:
                    return False
                for i in range(start, n):
                    x, y = pts[i]
                    ok = True
                    for cx, cy in chosen:
                        if abs(x - cx) + abs(y - cy) < d:
                            ok = False
                            break
                    if not ok:
                        continue
                    chosen.append((x, y))
                    if dfs(i + 1):
                        return True
                    chosen.pop()
                return False

            return dfs(0)

        lo, hi = 0, max_dist
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

