class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        m = len(queries)

        # If already zero array.
        if all(v == 0 for v in nums):
            return 0

        max_target = max(nums)  # ≤ 1000 by constraints

        # Iterate over prefix length k
