                # Collect values from first k queries covering i
                vals = []
                for q in range(k):
                    l, r, v = queries[q]
                    if l <= i <= r:
                        vals.append(v)

                # Subset sum DP
                dp = [False] * (target + 1)
                dp[0] = True
                for v in vals:
                    if v > target:
                        continue
                    for s in range(target, v - 1, -1):
