class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        # 1. Convert each row to a set of distinct values
        sets = [set(row) for row in properties]

        # 2. Build adjacency list according to the condition
        adj = [[] for _ in range(n)]
        for i in range(n):
            for j in range(i + 1, n):
                common = len(sets[i] & sets[j])   # number of distinct common integers
                if common >= k:
                    adj[i].append(j)
                    adj[j].append(i)

        # 3. Depth‑first search to count components
        visited = [False] * n
        def dfs(v: int) -> None:
            stack = [v]
            visited[v] = True
            while stack:
                cur = stack.pop()
                for nb in adj[cur]:
                    if not visited[nb]:
                        visited[nb] = True
                        stack.append(nb)

        components = 0
        for i in range(n):
            if not visited[i]:
                components += 1
                dfs(i)

        return components

