    def count_up_to(x: int) -> int:
        if x < 10:
            return 0
        digits = list(map(int, str(x)))

        @lru_cache(maxsize=None)
        def dp(pos: int, tight: bool, started: bool,
               top: int, valid: bool, have_other: bool) -> int:
            if pos == len(digits):
                return 1 if started and valid and have_other else 0
            limit = digits[pos] if tight else 9
            res = 0
            for d in range(limit + 1):
                ntight = tight and (d == limit)
                if not started:
                    if d == 0:
                        # still leading zeros
                        res += dp(pos + 1, ntight, False, 0, True, False)
                    else:
                        # first non‑zero digit becomes the top digit
                        res += dp(pos + 1, ntight, True, d, True, False)
                else:
                    # already have a top digit
                    nvalid = valid and (d < top)
                    # we now have at least one digit after the top digit
                    res += dp(pos + 1, ntight, True, top, nvalid, True)
            return res

        return dp(0, True, False, 0, True, False)

    answer = count_up_to(R) - count_up_to(L - 1)
    print(answer)


