class Fenwick:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, idx, delta):
        while idx <= self.n:
            self.bit[idx] += delta
            idx += idx & -idx

    def sum(self, idx):
        s = 0
        while idx:
            s += self.bit[idx]
            idx -= idx & -idx
        return s

    # smallest index such that prefix sum >= k (1-indexed)
    def kth(self, k):
        idx = 0
        bit = 1 << (self.n.bit_length() - 1)   # largest power of two <= n
        while bit:
            nxt = idx + bit
            if nxt <= self.n and self.bit[nxt] < k:
                k -= self.bit[nxt]
                idx = nxt
            bit >>= 1
        return idx + 1

