    # adjacency lists
    out_edges = [[] for _ in range(N)]
    in_edges = [[] for _ in range(N)]
    edges_list = []                     # for the "+1" case
    for i in range(N):
        for j in range(N):
            c = mat[i][j]
            if c != '-':
                out_edges[i].append((j, c))
                in_edges[j].append((i, c))
                edges_list.append((i, j))   # label irrelevant for middle edge

    INF = 10**9
    answers = [[-1] * N for _ in range(N)]

    # BFS for each source pair (s, t)
    for s in range(N):
        for t in range(N):
            dist = [[INF] * N for _ in range(N)]
            dq = deque()
            dist[s][t] = 0
            dq.append((s, t))

            while dq:
                a, b = dq.popleft()
                d = dist[a][b] + 1
                # paired step: outgoing from a , incoming to b with same label
                for na, ca in out_edges[a]:
                    for nb, cb in in_edges[b]:
                        if ca == cb and dist[na][nb] == INF:
                            dist[na][nb] = d
                            dq.append((na, nb))

            best = INF
            # case empty middle
            for v in range(N):
                if dist[v][v] < INF:
                    best = min(best, 2 * dist[v][v])
            # case one middle edge
            for (u, v) in edges_list:
                if dist[u][v] < INF:
                    best = min(best, 2 * dist[u][v] + 1)

            if best != INF:
                answers[s][t] = best

