def solve() -> None:
    data = sys.stdin.buffer.read().split()
    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    X = int(next(it))

    # adjacency for each parity: 0 = original, 1 = reversed
    adj0 = [[] for _ in range(N + 1)]
    adj1 = [[] for _ in range(N + 1)]
    for _ in range(M):
        u = int(next(it))
        v = int(next(it))
        adj0[u].append((v, 1))   # original orientation
        adj1[v].append((u, 1))   # reversed orientation (edge direction flipped)

    INF = 10**30
    # dist[parity][v]  parity 0 or 1
    dist0 = [INF] * (N + 1)
    dist1 = [INF] * (N + 1)

    start_v = 1
    dist0[start_v] = 0
    heap = [(0, start_v, 0)]  # (distance, vertex, parity)

    while heap:
        d, v, p = heapq.heappop(heap)
        if p == 0:
            if d != dist0[v]:
                continue
        else:
            if d != dist1[v]:
                continue

        # walk edges
        if p == 0:
            for to, w in adj0[v]:
                nd = d + w
                if nd < dist0[to]:
                    dist0[to] = nd
                    heapq.heappush(heap, (nd, to, 0))
        else:
            for to, w in adj1[v]:
                nd = d + w
                if nd < dist1[to]:
                    dist1[to] = nd
                    heapq.heappush(heap, (nd, to, 1))

        # toggle parity
        nd = d + X
        if p == 0:
            if nd < dist1[v]:
                dist1[v] = nd
                heapq.heappush(heap, (nd, v, 1))
        else:
            if nd < dist0[v]:
                dist0[v] = nd
                heapq.heappush(heap, (nd, v, 0))

    ans = min(dist0[N], dist1[N])
    sys.stdout.write(str(ans))

