# Fenwick tree
class BIT:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)
    def add(self, idx, val):
        while idx <= self.n:
            self.bit[idx] += val
            idx += idx & -idx
    def sum(self, idx):
        s = 0
        while idx > 0:
            s += self.bit[idx]
            idx -= idx & -idx
        return s
    def range_sum(self, l, r):
        return self.sum(r) - self.sum(l - 1)

def solve_one(N, arr):
    pos = [[] for _ in range(N + 1)]
    for i, v in enumerate(arr, 1):
        pos[v].append(i)
    intervals = []
    for x in range(1, N + 1):
        l, r = pos[x][0], pos[x][1]
        if r - l > 1:               # not originally adjacent
            intervals.append((l, r))
    # sort by left endpoint
    intervals.sort(key=lambda p: p[0])
    maxPos = 2 * N
    bit = BIT(maxPos)
    ans = 0
    for l, r in intervals:
        # number of previous intervals with right endpoint > r
        cnt = bit.sum(maxPos) - bit.sum(r)
        ans += cnt
        bit.add(r, 1)
    return ans

