    it = iter(data)
    N = int(next(it))
    P = [0] * (N + 1)          # 1‑based
    for i in range(1, N + 1):
        P[i] = int(next(it))

    # position of each value
    pos = [0] * (N + 1)
    for i in range(1, N + 1):
        pos[P[i]] = i

    ans = 0
    for v in range(1, N + 1):
        p = pos[v]
        if p > v:
            k = p - v                     # number of edges crossed
            ans += (v + p - 1) * k // 2   # sum of integers v .. p-1

    print(ans)

